246	    builder.withCredentials(parameters.getCredentialSet());
247	    builder.withClientConfiguration(awsConf);
248	    builder.withPathStyleAccessEnabled(parameters.isPathStyleAccess());
249	
250	    if (parameters.getMetrics() != null) {
251	      builder.withMetricsCollector(
252	          new AwsStatisticsCollector(parameters.getMetrics()));
253	    }
254	    if (parameters.getRequestHandlers() != null) {
255	      builder.withRequestHandlers(
